using System.Net;
using System.Net.Http.Headers;
using System.Runtime.CompilerServices;
using Styles.Tooling.Protobuf;

namespace Styles.Tooling.Grpc;

/// <summary>
/// A gRPC client: a method is an HTTP/2 POST on "/package.Service/Method", the framed message in the body,
/// and the result read in the trailers. For real: Grpc.Net.Client and the typed client generated by protoc.
/// </summary>
public sealed class GrpcClient(HttpClient http, string service)
{
    /// <summary>A unary call: one request, one response.</summary>
    public async Task<TResponse> Unary<TRequest, TResponse>(string method, TRequest request, TimeSpan? deadline = null,
        CancellationToken cancellation = default) where TRequest : notnull where TResponse : new()
    {
        var responses = new List<TResponse>();
        await foreach (var response in Stream<TRequest, TResponse>(method, request, deadline, cancellation))
            responses.Add(response);   // read to the end: the status only arrives afterwards, in the trailers
        return responses.Count == 1
            ? responses[0]
            : throw new GrpcError(GrpcStatus.Internal, $"{responses.Count} responses received for a unary call.");
    }

    /// <summary>A server stream: one request, responses as they come, then the final status.</summary>
    public async IAsyncEnumerable<TResponse> Stream<TRequest, TResponse>(string method, TRequest request, TimeSpan? deadline = null,
        [EnumeratorCancellation] CancellationToken cancellation = default) where TRequest : notnull where TResponse : new()
    {
        using var httpRequest = new HttpRequestMessage(HttpMethod.Post, $"/{service}/{method}")
        {
            Version = HttpVersion.Version20,
            VersionPolicy = HttpVersionPolicy.RequestVersionExact,   // HTTP/2 required (in clear text: "h2c")
            Content = new ByteArrayContent(GrpcFrame.Frame(Protobuf.Protobuf.Serialize(request)))
        };
        httpRequest.Content.Headers.ContentType = new MediaTypeHeaderValue(GrpcFrame.ContentType);
        httpRequest.Headers.TE.ParseAdd("trailers");
        if (deadline is { } d)
            httpRequest.Headers.Add("grpc-timeout", GrpcFrame.FormatTimeout(d));   // the server stops the work at the deadline

        using var response = await http.SendAsync(httpRequest, HttpCompletionOption.ResponseHeadersRead, cancellation);
        if (response.StatusCode != HttpStatusCode.OK)
            throw new GrpcError(GrpcStatus.Unavailable, $"HTTP response {(int)response.StatusCode}: this is not a gRPC server.");

        // "Trailers-only": an immediate error may arrive in the headers, without a body.
        CheckStatus(response.Headers);

        await using var stream = await response.Content.ReadAsStreamAsync(cancellation);
        while (await ReadFrame(stream, cancellation) is { } message)
            yield return Protobuf.Protobuf.Deserialize<TResponse>(message);

        if (!CheckStatus(response.TrailingHeaders))
            throw new GrpcError(GrpcStatus.Internal, "gRPC status missing from the trailers.");
    }

    /// <summary>A cut during the stream: cancellation if the client wanted it, otherwise server unavailable.</summary>
    private static async Task<byte[]?> ReadFrame(Stream stream, CancellationToken cancellation)
    {
        try
        {
            return await GrpcFrame.Read(stream, cancellation);
        }
        catch (Exception e) when (e is IOException or HttpRequestException)
        {
            cancellation.ThrowIfCancellationRequested();
            throw new GrpcError(GrpcStatus.Unavailable, $"Connection interrupted: {e.Message}");
        }
    }

    private static bool CheckStatus(HttpHeaders headers)
    {
        if (!headers.TryGetValues("grpc-status", out var values))
            return false;
        var status = (GrpcStatus)int.Parse(values.First());
        if (status == GrpcStatus.Ok)
            return true;
        var message = headers.TryGetValues("grpc-message", out var m) ? Uri.UnescapeDataString(m.First()) : "";
        throw new GrpcError(status, message);
    }
}
